const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const start_date = '2018-11-01';
  const end_date = '2018-11-30';
  const scale = 30; // Sentinel-2 resolution is 10m for B8, B4, but 30m for efficiency and general greenness.

  // Define polygons for Robinson Crusoe Island and Santa Clara Island
  // Robinson Crusoe Island (Más a Tierra)
  const robinsonCrusoeGeom = ee.Geometry.Polygon(
    [[[-78.94, -33.72],
      [-78.83, -33.72],
      [-78.83, -33.60],
      [-78.94, -33.60],
      [-78.94, -33.72]]]);

  // Santa Clara Island
  const santaClaraGeom = ee.Geometry.Polygon(
    [[[-79.04, -33.68],
      [-78.99, -33.68],
      [-78.99, -33.62],
      [-79.04, -33.62],
      [-79.04, -33.68]]]);

  // Function to mask clouds from Sentinel-2 SR data.
  function maskS2clouds(image) {
    var qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    var cloudBitMask = 1 << 10;
    var cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
  }

  // Function to calculate NDVI
  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  // Function to process an island's data
  async function processIsland(geometry, name) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(start_date, end_date)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 70)) // Filter out very cloudy images
      .map(maskS2clouds)
      .map(calculateNDVI);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`${name} Images: 0`);
      return { ndvi: null, pixels: 0, initialSize: 0 };
    }

    const composite = collection.median().clip(geometry);

    // Calculate valid pixel count
    const pixelCountResult = await composite.select('NDVI')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDVI').getInfo();

    if (pixelCountResult === 0 || pixelCountResult === null) {
      console.log(`${name} Images: ${initialSize} (Val: 0)`);
      return { ndvi: null, pixels: 0, initialSize: initialSize };
    }

    // Calculate mean NDVI
    const meanNdviResult = await composite.select('NDVI')
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDVI').getInfo();

    console.log(`${name} Images: ${initialSize} (Val: ${pixelCountResult}, NDVI: ${meanNdviResult !== null ? meanNdviResult.toFixed(3) : 'N/A'})`);
    return { ndvi: meanNdviResult, pixels: pixelCountResult, initialSize: initialSize };
  }

  // 2. Data Acquisition & Check for Robinson Crusoe Island
  const robinsonCrusoeData = await processIsland(robinsonCrusoeGeom, 'Robinson Crusoe');

  // 2. Data Acquisition & Check for Santa Clara Island
  const santaClaraData = await processIsland(santaClaraGeom, 'Santa Clara');

  // 3. Validation and Final Answer
  if (robinsonCrusoeData.initialSize === 0 || santaClaraData.initialSize === 0) {
    console.log("C1");
    return;
  }

  if (robinsonCrusoeData.pixels === 0 || santaClaraData.pixels === 0) {
    console.log("C2");
    return;
  }

  if (robinsonCrusoeData.ndvi === null || santaClaraData.ndvi === null) {
    console.log("C3");
    return;
  }

  if (robinsonCrusoeData.ndvi > santaClaraData.ndvi) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
